	CONSTRAINT "sign_in_approval_decided_check" CHECK (("sign_in_approval"."status" = 'pending') = ("sign_in_approval"."decided_at" is null)
        and ("sign_in_approval"."status" <> 'approved' or "sign_in_approval"."device_id" is not null)),
